"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["667"],{1037(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>s,contentTitle:()=>i,toc:()=>u,assets:()=>c});var n=JSON.parse('{"id":"explain/alms-account-management","title":"ALMS Onboarding and Ordering Guide for Sierra Wireless Partners","description":"reseller \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/explain/alms-account-management.md","sourceDirName":"explain","slug":"/explain/alms-account-management","permalink":"/personal-av-docs/docs/explain/alms-account-management","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/explain/alms-account-management.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"ALMS Onboarding and Ordering Guide for Sierra Wireless Partners","sidebar_label":"ALMS Onboarding and Ordering Guide for S","sidebar_position":99,"edition":"reseller","source":"https://doc.airvantage.net/reseller/alms-account-management","format":"md"}}'),a=o(4848),r=o(8453);let s={title:"ALMS Onboarding and Ordering Guide for Sierra Wireless Partners",sidebar_label:"ALMS Onboarding and Ordering Guide for S",sidebar_position:99,edition:"reseller",source:"https://doc.airvantage.net/reseller/alms-account-management",format:"md"},i,c={},u=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"reseller"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/reseller/alms-account-management",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsxs)(t.p,{children:["ALMS Onboarding and Ordering Guide for Sierra Wireless Partners\nAs a Sierra Wireless Partner and AirLink Management Service (ALMS) reseller, you have access to the same tools as your customers, so that you can manage your AirLink devices in ALMS. We also provide you with an extra set of utilities that let you easily manage your customer accounts, monitor their account status, identify which customers need to be contacted to buy more tokens, and track your customers\u2019 token orders.\nThis page provides an overview of these capabilities.\nInitializing Table Of Contents...\nCreating a New ALMS Account\nAs a Sierra Wireless Partner, you need to have an ALMS account to manage your customers. If you do not have an ALMS account, you can create an account through the general sign-up page. Please complete the following steps:\nCreate a new ALMS account:\nALMS Sign-up Page\nOpen a Customer Support ticket through the\nCustomer Support Portal\nSierra Wireless Partner Accounts\nAll authorized Sierra Wireless Partners are entitled to an ALMS account that you can use to manage a small fleet of your own AirLink gateways and routers, familiarize yourself with the product and do demos for your customers.\nAll Partner accounts:\nCan register up to 20 devices at no cost (these accounts have their token consumption suspended)\nHave access to the full ALMS feature-set, including ALMS ARA and other premium features\nHave a unique sign-up URL for customer account creation that links your customer\u2019s ALMS accounts to your Partner account\nAccess and Login\nAccount Management\nis a stand-alone web application connected to AirLink Management Service. You can access it using the following url:\n",(0,a.jsx)(t.a,{href:"https://na.airvantage.net/accounts",children:"https://na.airvantage.net/accounts"}),"\nThe login to be used is the same as the one you use for AirLink Management Services. Please note that you will only be able to access the Account Management web application if you are an Admin user of your company account. Alternatively, you can log in to ALMS and access the \u201CMy Account\u201D link.\nOnce logged in, there are three primary areas to the Partner page: My Token Stock, Subaccounts and Administration.\nMy Token Stock Tab\nThis tab lets you follow token consumption for your company account. This page does not display information about your customer\u2019s accounts. The tab is divided into 3 sections:\nSummary\nThis is a summary account statement, with details of your company\u2019s token stock and consumption.\nThe graph shows token use and purchases over the past 12 months.\nThe section on the right shows the evolution of your token stock for the current month, and how it is predicted to evolve based on the number of activated systems.\nThe number of activated systems shown is the peak number of systems activated within your company account for the current month. It is updated once per day. This is the number that will be considered to decrement the token stock at end of the month. Your token purchases from Sierra Wireless (as well as your sales of tokens to your own customers) are also considered when calculating the expected token balances.\nPlease note here the estimated date by which you will need to buy more ALMS Service Packs. This is a projection of when your tokens will be fully consumed. Future usage is predicted based on the previous month\u2019s peak.\nIn your Partner account you are limited to 20 devices, but you will not consume tokens on those devices. Your token balance is only important if you are using the Wholesale Model (see below) for token distribution to your customers, purchasing in bulk and transferring them to your customer\u2019s account. With this approach, it is critical that you always maintain an overall positive token balance, or you will not be able to complete token transfers.\nList Stock Updates\nThe table presents all the processed orders that you have submitted to Sierra Wireless (or your Distributor) over the past 12 months. Each time you submit a purchase order a new line appears in the table as soon as the PO has been processed. At the same time, you will be allocated the number of tokens corresponding to the number of Service Packs ordered, or they will be allocated to the customer\u2019s account.\nThis lets you track your fulfilled orders, with the ability to filter on order date, PO number, number of Service Packs purchased, or product reference.\nThis table also shows stock adjustments. A stock adjustment is done without any link to a new purchase order, in case of, for example, a credit/debit note, or if complimentary tokens are offered. Your token balance is then updated accordingly.\nReports\nThe Reports section shows the monthly token reports that have been sent to your company Admin contact(s). Links to reports for the last 12 months are shown. Every new month, the previous month\u2019s report is added to the list and is accessible online. For Resellers, these reports include your own token information as well as your customers\u2019.\nAdministration Tab\nThis is the tab where you can see and update your company account details and information. This is the default tab that is displayed when you login to the Account Management app.\nPlease note that this part of the documentation only summarizes the main screen as it relates to Partner accounts. It does not describe all the additional tabs. For full details of the Administration features, please refer to\nthe ALMS user documentation\nAccount Details\nThe main tab for Partners includes company name, ALMS uid, account type, offer class and company branding. You can upload an image file to customize this information if desired.\nALMS Support Contact Detail\nWithin ALMS, users that access the \u201CSupport\u201D link will be presented with your Customer Support information, if their account is associated with yours and you have updated this information. Please provide at least two of the three pieces of information. It is critical that you keep this information current, and it can be edited directly from this screen.\nSignup Details\nAll Sierra Wireless Partners are provided with a unique URL that your customers can use to create their new ALMS account, which is provided in this section. Give this link to your customers for them to create their own ALMS accounts. When they use this unique signup form, it will create an association between their ALMS account and your ALMS account, making you the Partner of record for that customer.\nSubaccounts Tab\nThe Subaccounts tab is specific to Sierra Wireless Partner accounts. This lets you manage your customer accounts, monitor their account status, identify which customers need to be contacted for token stock renewal, and also track their token orders.\nThe grid contains all your commercial subaccounts, along with the related account information such as where they stand in terms of token balances, whether their accounts are active or suspended, their current number of active systems, and when they will need to purchase additional tokens to continue using ALMS. There are several ways to filter and sort customer records, to help you easily identify accounts that need more tokens.\nFrom the subaccount grid, you can also add an order to a customer using the action buttons on the column to the right of the grid. Adding orders to the customer account will be your responsibility if you are using the wholesale token model. In this case, you are responsible for distributing tokens to your customers according to their purchases. As the tokens come from your ALMS account, please ensure that you have a sufficient token balance in your account prior to adding tokens to a customer account. The system will reject the transfer request if you do not.\nSubaccounts Details\nResellers can click on a subaccount in the list to drill down to the details of this specific customer. The details view is exactly the same view that the customer has in its own My Token Stock section, to assist you in providing support.\nThis tab also shows the evolution of subaccount token stock over the past 12 months as well as the different purchase orders passed by the customer (and eventual credit/debit notes).\nSelling ALMS Service Packs to a Customer\nOnce ALMS Service Packs are purchased, there are two options for distributing them to your customers.\nOrdering ALMS Service Packs\nALMS Service Packs can be purchased using the same Purchase Order mechanism that is in place for other Sierra Wireless products. Service Packs are ordered on-behalf of the customer, and discounts, if any, apply to each customer order.\nThe ALMS pricing is shown in the table below.\nSKU\nQuantity\nList Price\nALMS Service Pack\n9010177\nNo MoQ\n$20\nUsing the above pricing table as an example:\nThere is no minimum order quantity (MOQ) for ALMS Service Packs.\nIt is recommended that the customer order at least ONE ALMS Service Pack per device under management (one year of service). The intent is for customers to pre-purchase 12 months of service for EACH device they manage. If a customer has 100 devices under management and purchases 50 Service Packs this would provide them with only 6 months of pre-paid service.\nOne SKU for ordering ALMS Service Packs\n9010177 \u2013 1 ALMS Service Pack provides access to ALMS for 1 AirLink device for 12 months\nThere are two options for Sierra Wireless Partners to fulfill their customer\u2019s orders:\nDelegation Model\nIn the delegation model, the Partner delegates to Sierra Wireless the fulfillment of purchase orders, so that Sierra Wireless assigns tokens to the end customer account. Most Sierra Wireless Partners use this model as it simplifies the process for Partners.\nWhen delegating the assignment of tokens to Sierra Wireless, the Partner must ensure the end customer account is uniquely identified. Specifically, the Partner must provide the following information in the purchase order to Sierra Wireless:\nExact company name and/or uid of the ALMS account\nCompany Administrator email\nOnce Sierra Wireless has handled the purchase order, it will appear both in your Partner account in the My Token tab, as well in the subaccount list of orders, to mirror the effective transaction: Sierra Wireless sells tokens to you as the Partner; you sell on tokens to your end customers.\nAs a result of these transactions, any wholesale token balances held in your Partner account remains unchanged, while the token stock of the end customer is increased by the number of tokens corresponding to the ALMS Service Packs they have purchased. (One ALMS Service Pack consists of 12 tokens.)\nIf you opt for the delegation model, the Account Management tool will give you full transparency as when your customers\u2019 purchase orders have been fulfilled.\nWholesale Model\nThis new option lets Partners buy tokens from Sierra Wireless in wholesale batches. This means that you don\u2019t specify to which customer the Service Packs need to be provided. In this case, the tokens are simply allocated to you, the Partner, into your account.\nWith wholesale purchases, you don\u2019t need to link every customer order to an equivalent order to Sierra Wireless. You can now stock tokens in your account so that you can fulfill your customer orders directly, and with optimal responsiveness.\nPlease note that tokens just purchased from Sierra Wireless will appear in your\nMy Token Stock\ntab in the Summary panel and in the List Stock updates grid as soon as they are processed by Sierra Wireless Sales Operations. Once visible, they are available immediately to fulfill customer orders.\nA Partner using the wholesale option accepts responsibility to distribute tokens to end customers based on their purchase orders, and to track customer orders using the Account Management app, so that customer token balance is correctly managed.\nAllocating Service Packs to a customer from your Partner account is simple:\nSelect the customer to receive Service Packs, and click on the subaccount details\nIn the\nList stock updates\nsection, click on the button\nAdd token order\nto enter Service Packs related to a PO from the customer.\nEnter the number of Service Packs ordered by the customer. The\nAdd token order\npopup displays a summary of the customer token balance evolution based on fulfillment of the new order. If the customer has a negative token balance and the purchase order brings him back to positive, the account will automatically be reactivated.\nUpon clicking on\nConfirm Order\n, tokens are effectively taken from your wholesale stock to be allocated to the end customer. The newly entered order now appears in the grid.\nPlease note that by default, if a PO does not contain any identification of an end customer, Sierra Wireless will consider the order as using the wholesale model, and tokens will be added to your Partner account.\nCorrection of errors in an order, credit and debit notes\nYou can edit or even delete an order that has been entered for a subaccount, provided that the order has been entered during the current month. By editing the order, you will be able to change any of the fields previously entered, including the number of Service Packs allocated.\nIf an error has been committed before the current month, you can still fix the problem by doing a credit or debit note. To this purpose you can use the\nAdjust Stock\ncapability:\nSelect the customer for which you have to fix the stock of tokens and click on the subaccount details. In the\nList stock update\nsection, click on the button\nAdjust stock\n.\nEnter the number of tokens to be recredited or debited to the customer. The\nAdjust Stock\npopup displays a summary of the customer token stock update, based on tokens credited or debited via the credit/debit note. If the customer has a negative stock and a credit brings him back to positive, the account will automatically be reactivated.\nUpon clicking on\nConfirm Adjust Stock\n, tokens are effectively taken from your Partner account stock to be allocated to the end customer. In the case of a debit note, the converse is true: tokens are recredited to your Partner stock and debited from the end customer. The new stock adjustment now appears in the grid.\nIf you do not feel comfortable making the adjustments, please open a Customer Support ticket in the Customer Support Portal, and the Sierra Wireless Customer Support team will make the adjustment.\nAirLink Complete\nAll customers that purchase a supported Sierra Wireless gateway or router (AirLink LX, ES, GX, RV, MP series) is eligible to register their device to claim access to the first year of AirLink Complete. This includes access to ALMS for one year. Each successful registration adds one ALMS Service Pack (12 tokens) to the customer\u2019s ALMS account.\nAs a result, all customers should have an ALMS account. Renewals for AirLink Complete will be brought to the Partner of record for each customer account. We strongly encourage all Partners to register devices for their customers.\nPartner Registration - AirLink Complete\nCustomer Registration - AirLink Complete\nALMS Account Uses\nTrialing ALMS Pre-Purchase\nWe understand that many Partners will have customers that may want to trial products and that you may have loaned equipment to the customer and need a trial ALMS for a limited time.\nFor limited-duration trials, we can provide an account that supports a limited number of devices, to provide the customer with access. This account will provide access for up to 15 devices and includes the full ALMS and ALMS ARA functionality. Please use judgment in providing these accounts, as there are no automated means to limit the duration of the customer\u2019s use of the account. We will manually monitor the number of trial accounts and will work with our Partners to review and validate the continued use of any trial accounts.\nTo provide your Customer with a trial account:\nHave the Customer create an ALMS account using the standard process. They should use your Partner sign-up page to ensure the account association is created. If you do not have a Partner-specific sign up page, use the Sierra Wireless page:\nALMS Sign-up Page\nMake sure the Customer does not register any devices until after the account is converted (step 3).\nOpen a customer support ticket and request that the account be converted to an \u201CALMS Free Tier\u201D account. Provide the ALMS account UID and account name in the Customer Support Ticket.\nSet expectations with the Customer for the trial to last a reasonable duration (no more than 3 weeks) and advise that we can convert the account and maintain all the data, when they are ready to move to their \u201Cpermanent\u201D account. All devices, users, configurations and data will remain intact through the account conversion.\nUsing an ALMS Account to Transition Devices to AM or AMM\nIf a customer chooses to use an AirLink Manager or AirLink Mobility Manager server with their ALEOS devices, each of those devices must be configured with the server URL. The most effective way to do this is to use ALMS to push a template to each device, and Sierra Wireless will support our customers and partners by providing a free temporary ALMS account for this purpose. The transition account will be available for a reasonable length of time according to the project requirements, and will not require any tokens.\nFor more information, or to explore this approach please contact your Channel Business Manager (CBM)."]})]})}function d(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},8453(e,t,o){o.d(t,{R:()=>s,x:()=>i});var n=o(6540);let a={},r=n.createContext(a);function s(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);